func TestReviewV1OnlyCodec(t *testing.T) {
	c := encoding.GetCodec("proto")
	in := &pbv3.SearchRequestV3{Query: "hello"}
	want, err := protov1.Marshal(in)
	t.Logf("golang/protobuf Marshal: %x err=%v", want, err)
	got, err := c.Marshal(in)
	t.Logf("grpc codec Marshal: %x err=%v", got, err)
	out := &pbv3.SearchRequestV3{}
	err = c.Unmarshal(want, out)
	t.Logf("grpc codec Unmarshal: %+v err=%v", out, err)
}

