package status_test

import (
	"testing"

	"google.golang.org/grpc/codes"
	pbv3 "google.golang.org/grpc/reflection/grpc_testing_not_regenerate"
	"google.golang.org/grpc/status"
	"google.golang.org/protobuf/types/known/anypb"
	protov1 "github.com/golang/protobuf/proto"
	"github.com/golang/protobuf/ptypes"
	testpb "google.golang.org/grpc/interop/grpc_testing"
)

func TestReviewDetailsV1Only(t *testing.T) {
	st, err := status.New(codes.Internal, "x").WithDetails(&pbv3.SearchRequestV3{Query: "q"})
	if err != nil {
		t.Fatal(err)
	}
	for _, d := range st.Details() {
		_, isConcrete := d.(*pbv3.SearchRequestV3)
		_, isV1 := d.(protov1.Message)
		t.Logf("new Details() element type %T; is *SearchRequestV3=%v; is V1 proto.Message=%v", d, isConcrete, isV1)
	}
	// old behaviour
	for _, a := range st.Proto().Details {
		da := &ptypes.DynamicAny{}
		err := ptypes.UnmarshalAny((*anypb.Any)(a), da)
		_, isConcrete := da.Message.(*pbv3.SearchRequestV3)
		t.Logf("old ptypes.DynamicAny element type %T err=%v; is *SearchRequestV3=%v", da.Message, err, isConcrete)
	}
}

func TestReviewWithDetailsNilPtr(t *testing.T) {
	var m *testpb.SimpleRequest
	st, err := status.New(codes.Internal, "x").WithDetails(m)
	t.Logf("WithDetails(typed nil): st=%v err=%v", st, err)
	_, err = ptypes.MarshalAny(m)
	t.Logf("old ptypes.MarshalAny(typed nil): err=%v", err)
}
EOF
